contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function taking inputs: caller (address) is implicitly this contract
    // We simulate owner vs non-owner by using the fact that the deployed c's owner is the deployer (the test deployer),
    // and subsequent calls from this contract will be non-owner unless this contract is the owner.
    // To allow both possibilities we first read the owner, then branch behavior by attempting freezeAccount
    // from this contract (which will revert if this contract is not owner) and also attempt a call that should
    // succeed only when msg.sender == owner by calling from the owner via c.freezeAccount (owner can only be the deployer,
    // but we cannot make arbitrary external calls as other addresses). Therefore the property asserts the relation
    // between who is owner and whether this contract's call reverts, and that a successful call sets frozenAccount.

    function run(address target, bool freeze) public payable {
        require(target != address(0));
        // read current owner and frozen status
        address owner = c.owner();
        bool before = c.frozenAccount(target);

        // Try calling freezeAccount from this contract and capture whether it reverted
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the attempt, read frozen status again
        bool after = c.frozenAccount(target);

        // General rule to assert:
        // If this contract is the owner, the call must not revert and frozenAccount(target) must equal the requested value.
        // If this contract is not the owner, the call must revert and frozenAccount(target) must be unchanged.
        assert((address(this) == owner && reverted == false && after == freeze) ||
               (address(this) != owner && reverted == true && after == before));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: caller will be msg.sender of calls from this contract, so we simulate by calling c methods directly.
    // We take a boolean callByOwner which when true we first ensure this contract is the owner by reading c.owner() and
    // if not, we try to make this contract the owner by relying on initial owner being the deployer (the checker deploys c fresh
    // with owner set to deployer, which is the test deployer, not this contract). To keep this general, we do NOT assume ownership.
    // Instead we observe owner before and after trying owned(), and check the general property: success implies owner changed to msg.sender,
    // failure implies owner unchanged.
    function run() public payable {
        // read owner before
        address ownerBefore = c.owner();
        bool reverted;
        // call owned() and catch revert
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter = c.owner();
        // If call did not revert, ownerAfter must equal address(this). If it reverted, ownerAfter must equal ownerBefore.
        assert(reverted ? ownerAfter == ownerBefore : ownerAfter == address(this));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bool callOwned) public payable {
        require(true);
        address ownerBefore = c.owner();
        bool reverted;
        // perform the call as a top-level statement; use callOwned to choose whether to attempt the call
        if (callOwned) {
            try c.owned() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // if we don't call, treat as not reverted and owner unchanged path
            reverted = true;
        }
        address ownerAfter = c.owner();
        // If the call did not revert then owner must have become this contract; if it reverted (or we didn't call) owner must be unchanged
        assert(reverted ? ownerAfter == ownerBefore : ownerAfter == address(this));
    }
    receive() external payable { }
}

