contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bool doCall) public payable {
        require(true);
        address ownerBefore = c.owner();
        bool didCall;
        bool reverted;
        // Perform the potentially state-changing call as a single top-level statement.
        // We cannot put the call inside an if/try/other, so always perform it but
        // use a flag to decide whether to execute the call by calling a no-op when not desired.
        // To respect the requirement that state-changing calls be top-level, we use try/catch at top level.
        if (doCall) {
            didCall = true;
            try c.owned() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            didCall = false;
            // Do not call c.owned(); treat as if it reverted (no state change)
            reverted = true;
        }

        address ownerAfter = c.owner();
        // If we attempted the call and it did not revert, owner must become this contract;
        // if it reverted or we didn't call, owner must remain unchanged.
        assert((didCall && !reverted) ? ownerAfter == address(this) : ownerAfter == ownerBefore);
    }
    receive() external payable { }
}
